const response = await fetch(`${baseUrl}/messages/456`, {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${token}`,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({ body: 'Olá! Como podemos ajudar?' })
});
if (!response.ok) throw new Error(await response.text());
// HTTP 200 sem corpo: não chame response.json().
